colors={'B1':'#ECF3E4','B2':'#ECF3E4','ST':'#F5EACF','ST2':'#F5EACF','ST3':'#F5EACF','BA':'#DBEDEC','BAL':'#EAF2ED','SH':'#F3F4EF','SR':'#F3F4EF'}
def drawplan(d,labels=True,fixtures=False,rooms_only=False):
    for room in d['rooms']:world(room['points'],'#A6B4AA',.45,colors.get(room['id'],'#EDF0E9'),True)
    if not rooms_only:
        for w in d['walls']:
            a,b=w['a'],w['b'];u=[b[j]-a[j] for j in (0,1)];l2=sum(t*t for t in u)
            openings=[]
            for oo in d['openings']:
                if oo['wall']!=w['id']:continue
                lo,hi=sorted(sum((pt[j]-a[j])*u[j] for j in (0,1))/l2 for pt in [oo['a'],oo['b']]);openings.append((max(0,lo),min(1,hi),oo))
            prev=0
            for lo,hi,o in sorted(openings,key=lambda e:e[0])+[(1,1,None)]:
                if lo>prev:world([cut(a,b,prev),cut(a,b,lo)],teal if w['kind']=='new' else ink,max(1.2,w['t']*S*.76))
                prev=max(prev,hi)
                if not o:continue
                a1,b1=cut(a,b,lo),cut(a,b,hi);kind=o['kind']
                if 'window' in kind or kind=='glazed_door':world([a1,b1],'#49949C',2)
                if kind in ['door','entry','entry_common','glazed_door']:
                    pivot=b1 if o['hinge']=='b' else a1;other=a1 if o['hinge']=='b' else b1
                    dx,dy=o['swing'];rr=math.dist(a1,b1);en=(pivot[0]+rr*dx,pivot[1]+rr*dy)
                    world([pivot,en],grey,.8)
                    angle=math.atan2(other[1]-pivot[1],other[0]-pivot[0]);angle1=math.atan2(dy,dx);step=(angle1-angle+math.pi)%(2*math.pi)-math.pi
                    world([(pivot[0]+rr*math.cos(angle+step*j/12),pivot[1]+rr*math.sin(angle+step*j/12)) for j in range(13)],grey,.48,dash=(2,2))
    bp=base['rooms']['balcony']['points'];world(bp[4:]+bp[:4],teal,1.8);world(d['column'],ink,1,ink,True)
    for a,b in [(bp[5],bp[0]),(bp[4],bp[5]),(bp[2],bp[3])]:
        div=math.ceil(math.dist(a,b)/1.25)
        for j in range(1,div):
            x,y=xy(cut(a,b,j/div));box(x-1.8,y-1.8,3.6,3.6,teal)
    if fixtures:
        for v in d['furniture']:
            x,y,w,h=v['x'],v['y'],v['w'],v['d'];a=xy((x,y));box(*a,w*S,h*S,'#E7D9C2','#8E795E',.72)
            if v['kind']=='bed':
                box(a[0]+2,a[1]+h*S-15,w*S-4,12,'#FDFAF0','#907F66',.5)
            elif v['kind'] in ['hob','sink','dishwasher','fridge','washer','toilet','basin']:mark((x+w/2,y+h/2),v['id'],6)
    if labels:
        pos=positions.copy()
        if d['entry']==1:pos.update(B2=(1.71,-3.50),ST2=(4.28,-3.35))
        if d['entry']==2:pos.update(BA=(4.79,-3.75),H1=(6.33,-3.05))
        for room in d['rooms']:
            k=room['id'];pt=pos[k]
            mark(pt,shorthand[k],7 if k in ['H1','H2','SR','SH'] else 8.5)
            mark(pt,f"{room['area']:.2f}",7,-9,grey)
    scale()
def key(x,y,items):
    for color,lab in items:line((x,y+3),(x+26,y+3),color,2);txt(x+36,y,lab,10);y-=18
    return y
