detail(35,709,'Ա  /  Ապակեպատման ստորին հանգույց',[
((45,-118),(290,-118),ink,8),((45,-101),(253,-112),teal,2),((241,-111),(241,-57),teal,3),((249,-111),(249,-57),teal,2),((228,-102),(261,-102),ink,5),((255,-106),(285,-106),blue,1.6),((285,-106),(280,-102),blue,1.6)],
'Արտաքին պրոֆիլ՝ ջերմախզիչով։ Արտաքին անձրևաջուրը՝ պրոֆիլի դրենաժից դեպի կաթոցիկ և գործող օրինական ընդունիչ։ Ներսի կոնդենսատը՝ հավաքիչով։ Չփակել ջրահեռացման անցքերը։ Չափել սալի իրական թեքությունն ու եզրը։')
detail(605,709,'Բ  /  Սյուն և ուղղաձիգ բաժանում',[
((38,-103),(362,-103),teal,2),((140,-110),(174,-110),ink,10),((141,-85),(174,-85),ink,10),((142,-84),(142,-111),ink,7),((173,-84),(173,-111),ink,7),((157,-84),(157,-48),grey,4)],
'Թվայնացված սյուն՝ մոտ 209 × 193 մմ։ Նոր միջնորմի ծայրը կանգ է առնում սյան երեսին՝ ճկուն հպմամբ։ Սյունը պահել լրիվ հատույթով։ Ապակեփաթեթի հանգույցը զատել կոնստրուկցիայից։ Շարժման կարն ու ամրացումը հաշվարկել։')
detail(35,437,'Գ  /  Ներսի և պատշգամբի շեմ',[
((35,-103),(215,-103),ink,5),((215,-103),(250,-103),teal,4),((250,-105),(380,-114),grey,4),((242,-103),(242,-53),teal,3),((250,-103),(250,-53),teal,2),((207,-117),(375,-128),blue,1.7)],
'Ջերմամեկուսացումը շարունակել շեմի տակ։ Ջրամեկուսացումը բարձրացնել պրոֆիլին և փակել ծայրերը։ Շեմի նախագծային վերին ելուստը ≤25 մմ՝ կիրառելիությունը ստուգել։ Բացվող փեղկը դուրս է շրջվում պատշգամբի ազատ գոտի։ Արևապաշտպան էկրանի ամրացումը ստուգել քամով։')
detail(605,437,'Դ  /  Սանհանգույց և փակվող դուռ',[
((35,-91),(160,-91),ink,5),((160,-91),(170,-99),ink,3),((170,-99),(367,-106),teal,3),((170,-108),(367,-114),blue,2),((354,-112),(354,-74),blue,2),((236,-106),(256,-106),ink,5)],
'Անջրաթափանց թաղանթ՝ առկա սալի վերևում և պատերին ծալված։ Հոսակ՝ կոյուղուն կապվող հերմետիկ օղակով։ Եթե կիրառվում է 160-րդ կետի բացառությունը՝ բավարարել նշված 30 մմ-ից ավելի իջեցման պահանջը։ Պատրաստի բարձրությունը, մուտքի մատչելիությունը և կոյուղին ստուգել միասին։')
note(45,158,'Դռնատեղի լցվածք','№1-ի 622 մմ գոտին լրացնել համարժեք խտությամբ և հրդեհային հատկությամբ համակարգով, ակոսային կամ թույլատրված կողային կապերով։ Վերևում կիրառել նյութին համապատասխան սեղմվող միացում, վերականգնել երկու երեսների հարդարանքը։ Կից կրող տարրերի հորատումը պահանջում է կոնստրուկտորի մանրամասն։',1090);show()
pg('Ճ-10','Իրավական և նախագծային ստուգումներ','Պաշտոնական հրապարակումների ընթերցում՝ 23.11.2026։ Հղումները սեղմելի են։ Շենքի հասցեն, հարկը, սեփականության վկայականը և մասնագիտական հաստատումները չեն տրամադրվել։')
sources=[('Ա • ՀՀՇՆ 31-01-2014','https://www.arlis.am/hy/acts/208949/latest'),('Բ • ՀՀՇՆ 22-03-2017','https://arlis.am/hy/acts/112988'),('Գ • Բազմաբնակարան շենքի կառավարման մասին ՀՀ օրենք','https://www.arlis.am/hy/acts/223635'),('Դ • ՀՀ կառավարության N 596-Ն որոշում','https://www.arlis.am/hy/acts/228582')]
rows=[['Հարց / պաշտոնական հիմք','Կիրառումը այս բնակարանում','Ով և ինչ է ստուգում'],
['Ա • կետեր 177–181 և 184, Բ • բնակելի տների աղյուսակ','Կետ 181-ի նախնական բացվածք/հատակ միջակայքը՝ 1:8–1:5.5։ Կետ 184-ի արևահարման պայմանը՝ մեկից երեք սենյականոց բնակարանի առնվազն մեկ բնակելի սենյակի համար 2.5 ժամ՝ նշված սեզոնին և երկրաչափական պայմաններով։','Լուսատեխնիկ՝ կողմնորոշում, փողոցի կտրվածք, ԲԼԳ, փեղկերի ու քիվի ստվեր։ Կետ 178-ի անմիջական բնական լույսի պահանջը գնահատել փակ պատշգամբի փաստացի լուծմամբ։'],
['Ա • կետեր 38 և 44','Երկու սենյակների մաքուր մակերեսներն են 13.55 և 10.09 մ²։ Կետ 38-ի 8 մ² շեմը սահմանված է պետական, համայնքային ու սոցիալական ֆոնդի համար։ Մասնավոր բնակարանի կիրառելի ծրագիրը ճշտվում է առանձին։ R2 առաստաղ՝ 2.80 մ ենթադրություն։','Ճարտարապետ՝ հաստատել ֆոնդը, սենյակների կարգավիճակը և մաքուր բարձրությունը։ Մեկ սենյակը տեղավորում է երկտեղանոց, մյուսը՝ մեկտեղանոց մահճակալ։'],
['Ա • կետեր 159–161','Նոր սանհանգույցը նախկին ննջարանի տեղում է, իսկ B2-ը մասամբ նախկին բաղնիքի տեղում։ Կենտրոնացնել թե՛ ներքևի, թե՛ վերևի բնակարանների թաց գոտիները։ Կետ 160-ի բացառությունը կապված է պատվիրատուի առաջադրանքի ու ջրամեկուսացման, իջեցման և հոսակի պահանջների հետ։','Կոնստրուկտոր ու սանտեխնիկ՝ երկու հարակից հարկերի փաստաթղթեր, սալի շերտեր, անվտանգ հատակի տարբերություն։'],
['Գ • հոդվածներ 6–8','Կրող կոնստրուկցիաներն ու ընդհանուր ցանցերը հատուկ կարգավիճակ ունեն։ Հոդված 8-ը տարբերակում է հարակից սեփականատիրոջ սահմանը, ընդհանուր գույքով կոմունիկացիայի պայմանները և ուրիշի իրավունքի սահմանափակումը։','Գրանցման քաղվածք, հարևանի օգտագործման իրավունքի ստուգում, պահանջվող դեպքում համաձայնություն։ Կառավարման մարմնին նախապես տեղեկացնել։'],
['Դ • հավելված 1, կետեր 26–27, 136, հավելված 4, ցանկ 1','Ընթացիկ նորոգման անվանումը բավարար չէ ճակատային բացվածքի, պատշգամբի ապակեպատման կամ ջերմային սահմանի փոփոխության համար։ Յուրաքանչյուր գործողության ռիսկայնությունը և թույլտվության ընթացքը ճշտվում են հասցեով ու աշխատանքների կազմով։','Իրավասու համայնք և կոնստրուկտոր՝ առանձին գնահատել նոր մուտքը, ապակեպատումը և 1 մ ընդլայնումը։']]
